#!/usr/bin/env python3
"""CSV Insights: small dependency-free CSV filtering and aggregation tool."""

from __future__ import annotations

import argparse
import csv
import json
import sys
from collections import OrderedDict
from decimal import Decimal, InvalidOperation
from pathlib import Path


class CsvInsightsError(Exception):
    """An expected input or command-line error."""


def parse_filter(value: str) -> tuple[str, str]:
    """Parse COLUMN=VALUE, allowing equals signs in VALUE."""
    if "=" not in value:
        raise argparse.ArgumentTypeError("filters must have the form COLUMN=VALUE")
    column, expected = value.split("=", 1)
    if not column:
        raise argparse.ArgumentTypeError("filter column must not be empty")
    return column, expected


def read_csv(filename: str) -> tuple[list[str], list[tuple[int, dict[str, str]]]]:
    """Read and validate CSV, retaining physical record numbers for diagnostics."""
    try:
        stream = open(filename, "r", encoding="utf-8-sig", newline="")
    except OSError as exc:
        raise CsvInsightsError(f"cannot open input file: {exc}") from exc

    try:
        with stream:
            reader = csv.reader(stream)
            try:
                headers = next(reader)
            except StopIteration:
                raise CsvInsightsError("input CSV is empty")
            except csv.Error as exc:
                raise CsvInsightsError(f"malformed CSV header: {exc}") from exc

            if not headers or any(not header for header in headers):
                raise CsvInsightsError("headers must be non-empty")
            duplicates = sorted({h for h in headers if headers.count(h) > 1})
            if duplicates:
                raise CsvInsightsError("headers must be unique: " + ", ".join(duplicates))

            rows: list[tuple[int, dict[str, str]]] = []
            try:
                for row in reader:
                    record_number = reader.line_num
                    if len(row) != len(headers):
                        raise CsvInsightsError(
                            f"row {record_number} has {len(row)} fields; expected {len(headers)}"
                        )
                    rows.append((record_number, dict(zip(headers, row))))
            except csv.Error as exc:
                raise CsvInsightsError(f"malformed CSV near row {reader.line_num}: {exc}") from exc
    except UnicodeError as exc:
        raise CsvInsightsError(f"cannot decode input CSV as UTF-8: {exc}") from exc
    return headers, rows


def decimal_text(value: Decimal) -> str:
    """Return non-exponential, minimal Decimal text while preserving nonzero scale."""
    if value == 0:
        return "0"
    text = format(value, "f")
    if "." in text:
        text = text.rstrip("0").rstrip(".")
    return text


def decimal_cell(value: str, row_number: int, column: str) -> Decimal:
    if not value:
        raise CsvInsightsError(f"invalid numeric value at row {row_number}, column '{column}': blank")
    try:
        number = Decimal(value)
    except InvalidOperation:
        raise CsvInsightsError(
            f"invalid numeric value at row {row_number}, column '{column}': {value!r}"
        ) from None
    if not number.is_finite():
        raise CsvInsightsError(
            f"invalid numeric value at row {row_number}, column '{column}': {value!r}"
        )
    return number


def validate_columns(headers: list[str], args: argparse.Namespace) -> None:
    requested = [column for column, _ in args.where]
    requested += [column for column in (args.group_by, args.sum, args.avg) if column]
    unknown = sorted(set(requested) - set(headers))
    if unknown:
        raise CsvInsightsError("unknown column(s): " + ", ".join(unknown))


def build_output(headers: list[str], rows: list[tuple[int, dict[str, str]]], args: argparse.Namespace):
    filtered = [row for _, row in rows if all(row[column] == expected for column, expected in args.where)]
    if not args.group_by:
        return headers, filtered

    groups: dict[str, dict[str, object]] = {}
    for row_number, row in rows:
        if not all(row[column] == expected for column, expected in args.where):
            continue
        key = row[args.group_by]
        group = groups.setdefault(key, {"count": 0, "sum": Decimal(0), "avg": Decimal(0)})
        group["count"] = int(group["count"]) + 1
        if args.sum:
            group["sum"] = Decimal(group["sum"]) + decimal_cell(row[args.sum], row_number, args.sum)
        if args.avg:
            group["avg"] = Decimal(group["avg"]) + decimal_cell(row[args.avg], row_number, args.avg)

    output_headers = [args.group_by]
    if args.sum:
        output_headers.append(f"sum_{args.sum}")
    if args.avg:
        output_headers.append(f"avg_{args.avg}")
    output_rows = []
    for key in sorted(groups):
        group = groups[key]
        result: dict[str, str] = {args.group_by: key}
        if args.sum:
            result[f"sum_{args.sum}"] = decimal_text(Decimal(group["sum"]))
        if args.avg:
            result[f"avg_{args.avg}"] = decimal_text(Decimal(group["avg"]) / int(group["count"]))
        output_rows.append(result)
    return output_headers, output_rows


def parse_args(argv: list[str]) -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="Filter and aggregate an RFC-4180 CSV file.")
    parser.add_argument("input", help="input CSV file")
    parser.add_argument("--where", action="append", type=parse_filter, default=[], metavar="COLUMN=VALUE")
    parser.add_argument("--group-by", metavar="COLUMN")
    parser.add_argument("--sum", dest="sum", metavar="COLUMN")
    parser.add_argument("--avg", metavar="COLUMN")
    parser.add_argument("--output", choices=("json", "csv"), default="json")
    args = parser.parse_args(argv)
    if (args.sum or args.avg) and not args.group_by:
        parser.error("--sum and --avg require --group-by")
    if args.group_by and not (args.sum or args.avg):
        parser.error("--group-by requires --sum and/or --avg")
    return args


def emit(headers: list[str], rows: list[dict[str, str]], output: str) -> None:
    if output == "json":
        json.dump(rows, sys.stdout, ensure_ascii=False, separators=(",", ":"))
        sys.stdout.write("\n")
    else:
        writer = csv.DictWriter(sys.stdout, fieldnames=headers, lineterminator="\n")
        writer.writeheader()
        writer.writerows(rows)


def main(argv: list[str] | None = None) -> int:
    try:
        args = parse_args(sys.argv[1:] if argv is None else argv)
        headers, rows = read_csv(args.input)
        validate_columns(headers, args)
        output_headers, output_rows = build_output(headers, rows, args)
        emit(output_headers, output_rows, args.output)
        return 0
    except CsvInsightsError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    sys.exit(main())
